PATCHES = [{'path': 'DBM-AntorusBurningThrone/AntorusWarCouncil.lua', 'source': {'path': 'DBM-AntorusBurningThrone/AntorusWarCouncil.lua', 'mode': 'GENERATED', 'folder': 'common_research_only'}, 'before_sha256': '622f39b4f97ebd4538e7dc4c60bf4778df701b671ab02dcbd1efee286c988356', 'after_sha256': 'fdf9dd3d43e216069550ed2748979c7dce7cb2fe9a9c41b37f2962f385459413', 'operations': [[105, 157, 'mod:SetRevision(20261107000001) -- Normal Fusillade timing; heroic unchanged\n'], [9481, 9557, '\t\ttimerFusilladeCD:Start(self:IsNormal() and 30 or 25.5, self.vb.FusilladeCount+1) --точно под героик\n'], [9584, 9637, '\t\t\tcountdownFusillade:Start(self:IsNormal() and 30 or 25.5) --точно под героик\n'], [11010, 11134, '\t\t\ttimerFusilladeCD:Start(self:IsNormal() and 24 or 19, self.vb.FusilladeCount+1) --Шквальный огонь\n\t\t\tcountdownFusillade:Start(self:IsNormal() and 24 or 19) --Шквальный огонь\n'], [12824, 12948, '\t\t\ttimerFusilladeCD:Start(self:IsNormal() and 24 or 19, self.vb.FusilladeCount+1) --Шквальный огонь\n\t\t\tcountdownFusillade:Start(self:IsNormal() and 24 or 19) --Шквальный огонь\n']]}, {'path': 'DBM-AntorusBurningThrone/Hasabel.lua', 'source': {'path': 'DBM-AntorusBurningThrone/Hasabel.lua', 'mode': 'DONOR', 'donor': 'S01', 'source_path': 'DBM-AntorusBurningThrone/Hasabel.lua', 'sha256': 'f7713659976c1ffdcc62d5b3615e31a6fb4cb8d1abe54ac4ccdba6645ce2c31a'}, 'before_sha256': 'f7713659976c1ffdcc62d5b3615e31a6fb4cb8d1abe54ac4ccdba6645ce2c31a', 'after_sha256': '4222f85b6fb304664a0d68151dd88742cc243a004e9afdd0be14d624d8b1f2a6', 'operations': [[108, 161, 'mod:SetRevision(20261107000001) -- Normal transport portal timing only\r\n'], [13196, 13231, '\t\t\ttimerTransportPortalCD:Start(self:IsNormal() and 40 or nil)\r\n']]}, {'path': 'DBM-EmeraldNightmare/Ilgynoth.lua', 'source': {'path': 'DBM-EmeraldNightmare/Ilgynoth.lua', 'mode': 'DONOR', 'donor': 'S01', 'source_path': 'DBM-EmeraldNightmare/Ilgynoth.lua', 'sha256': '0fcdd48f280de77d37c56bc21ba83a98ff1fe5489cb7045742497577e198da34'}, 'before_sha256': '0fcdd48f280de77d37c56bc21ba83a98ff1fe5489cb7045742497577e198da34', 'after_sha256': '54d3495f8ae7d9271fbc78849a931a7e6594d79a60e09f88fd4b998293353740', 'operations': [[104, 157, 'mod:SetRevision(20261103000001) -- RAID-20261103-TEST001 / private TEST002\r\n'], [21270, 21290, '\t\tlocal bossUnitID = "boss"..i\r\n']]}, {'path': 'DBM-EmeraldNightmare/Nythendra.lua', 'source': {'path': 'DBM-EmeraldNightmare/Nythendra.lua', 'mode': 'DONOR', 'donor': 'S01', 'source_path': 'DBM-EmeraldNightmare/Nythendra.lua', 'sha256': 'c2160e9959d019c4fcd94882fd3747c45265518668bd849735a2f62dbc631ddb'}, 'before_sha256': 'c2160e9959d019c4fcd94882fd3747c45265518668bd849735a2f62dbc631ddb', 'after_sha256': '6fb6667415b8fe37078d6624ce6f04a3e03ef0b0939c756cfdb0bea43c1e33f9', 'operations': [[104, 157, 'mod:SetRevision(20261103000001) -- RAID-20261103-TEST001 / private TEST002\r\n'], [897, 963, 'local warnRotFades\t\t\t\t\t= mod:NewFadesAnnounce(204463, 1, nil, nil, "announce203096fades")\r\n-- Keep the existing saved option while correcting its displayed spell.\r\nDBM:GetModLocalization(1703):SetOptionLocalization({\r\n\tannounce203096fades = DBM_CORE_AUTO_ANNOUNCE_OPTIONS.fades:format(204463)\r\n}) --Гниль\r\n']]}, {'path': 'DBM-Party-BfA/TheUnderrot/SporecallerZancha.lua', 'source': {'path': 'DBM-Party-BfA/TheUnderrot/SporecallerZancha.lua', 'mode': 'GENERATED', 'folder': 'active_research_only'}, 'before_sha256': '43684256933016be7e7be6a1545d6bc5e3a680baa6ce09593c68f55d358dd9d2', 'after_sha256': '73bd699fcffe41e0fea2a57fa5fcb02c1d4e3c938bfe6248cfeb984c5120c4f1', 'operations': [[93, 125, 'mod:SetRevision(20261101000001)\n-- Private BFA-20261101-TEST001; public 0.1.16 remains unchanged.\n'], [3044, 3044, '-- UWoW delivers Volatile Pods as a boss1 UNIT success, without CLEU success.\n-- Share the existing warning/AI path so dual delivery cannot teach a false short CD.\nfunction mod:RVUWoWVolatilePods()\n if self:AntiSpam(2, "UR-273271") then\n  specWarnVolatilePods:Show()\n  specWarnVolatilePods:Play("watchstep")\n  timerVolatilePodsCD:Start()\n end\nend\n\n'], [3295, 3396, '  self:RVUWoWVolatilePods()\n'], [8018, 8109, 'function mod:RVComplete_UNIT_SPELLCAST_SUCCEEDED(unit, _, spellId, legacyRank, legacySpellId)\n'], [8145, 8187, '\tif spellId == 273271 and unit == "boss1" then--Volatile Pods\n'], [8224, 8224, '  self:RVUWoWVolatilePods()\n']]}, {'path': 'DBM-Party-BfA/TheUnderrot/UnderrotTrash.lua', 'source': {'path': 'DBM-Party-BfA/TheUnderrot/UnderrotTrash.lua', 'mode': 'GENERATED', 'folder': 'active_research_only'}, 'before_sha256': 'b648ac28b84e96035c36cb97d29aae9d8d7376768c1278aa6d82812604c92fca', 'after_sha256': '1bbe85a14d202bed84eef48f68d52c6d2ed1400b3d48aeed0c750e476f531cc8', 'operations': [[98, 130, 'mod:SetRevision(20261101000001)\n-- Private BFA-20261101-TEST001; public 0.1.16 remains unchanged.\n'], [11535, 11597, '\t\trvComplete_timerMaddeningGazeCD:Start(self:IsHard() and 14.9 or nil, args.sourceGUID) -- UWoW Mythic/M+: cross-run CAST_START floor\n'], [15752, 15813, '\t\trvComplete_timerAbyssalReachCD:Start(self:IsHard() and 14.9 or nil, args.sourceGUID) -- UWoW Mythic/M+: cross-run CAST_START floor\n'], [16000, 16055, '\t\trvComplete_timerWarcryCD:Start(self:IsHard() and 23.9 or nil, args.sourceGUID) -- UWoW Mythic/M+: cross-run CAST_START floor\n'], [16179, 16240, '\t\trvComplete_timerWickedFrenzyCD:Start(self:IsHard() and 15.4 or nil, args.sourceGUID) -- UWoW Mythic/M+: cross-run CAST_START floor\n']]}, {'path': 'DBM-Party-Legion/ReturnToKarazhan/Curator.lua', 'source': {'path': 'DBM-Party-Legion/ReturnToKarazhan/Curator.lua', 'mode': 'GENERATED', 'folder': 'common_research_only'}, 'before_sha256': 'ece7316885899cacdc3be9c8b5f4f2a9c7538163ec32a180f29ede202d2c9067', 'after_sha256': 'f86bf1e69440befa7c654437095ac06feba1be54041a5fdfdcedadc6d4d2e545', 'operations': [[0, 5263, '-- UNOFFICIAL overlay CURATOR-20261029-TEST001 for DBM RV*+ 0.1.16 TEST.\r\n-- Countdown ends at the existing dodge warning; only NPC 114249 receives icons.\r\nlocal mod\t= DBM:NewMod(1836, "DBM-Party-Legion", 11, 860)\r\nlocal L\t\t= mod:GetLocalizedStrings()\r\n\r\nmod:SetRevision(("$Revision: 17750 $"):sub(12, -3))\r\nmod:SetCreatureID(114462)\r\nmod:SetEncounterID(1964)\r\nmod:SetZone()\r\nmod:SetMinSyncRevision(17750)\r\nmod:SetUsedIcons(8, 7, 6, 5, 4, 3, 2, 1)\r\n--mod:SetHotfixNoticeRev(14922)\r\n--mod.respawnTime = 30\r\n\r\nmod.noNormal = true\r\n\r\nmod:RegisterCombat("combat")\r\n\r\nmod:RegisterEventsInCombat(\r\n\t"SPELL_CAST_SUCCESS 234416",\r\n\t"SPELL_AURA_APPLIED 227254 227257",\r\n\t"SPELL_AURA_APPLIED_DOSE 227257",\r\n\t"SPELL_AURA_REMOVED 227254",\r\n\t"SPELL_PERIODIC_DAMAGE 227465",\r\n\t"SPELL_PERIODIC_MISSED 227465",\r\n\t"SPELL_SUMMON 227267",\r\n\t"UNIT_DIED",\r\n\t"UNIT_DESTROYED",\r\n\t"UNIT_SPELLCAST_SUCCEEDED boss1"\r\n)\r\n\r\n--Смотритель и прошляпанное очко Мурчаля Прошляпенко [✔]\r\nlocal warnOverload\t\t\t\t\t= mod:NewStackAnnounce(227257, 4, nil, nil, 2) --Перегрузка\r\nlocal warnAdds\t\t\t\t\t\t= mod:NewSpellAnnounce(227267, 3, nil, "Healer") --Призыв нестабильной энергии\r\nlocal warnEvo\t\t\t\t\t\t= mod:NewSpellAnnounce(227254, 3, nil, "Healer") --Прилив сил\r\n\r\nlocal specWarnPowerDischarge2\t\t= mod:NewSpecialWarningDodge(227279, nil, nil, nil, 2, 2) --Разряд энергии\r\nlocal specWarnAdds\t\t\t\t\t= mod:NewSpecialWarningSwitch(227267, "-Healer", nil, nil, 1, 2) --Призыв нестабильной энергии\r\nlocal specWarnPowerDischarge\t\t= mod:NewSpecialWarningYouMove(227465, nil, nil, nil, 1, 2) --Разряд энергии\r\nlocal specWarnEvo\t\t\t\t\t= mod:NewSpecialWarningMoreDamage(227254, "-Healer", nil, nil, 3, 2) --Прилив сил\r\nlocal specWarnEvo2\t\t\t\t\t= mod:NewSpecialWarningSoon(227254, nil, nil, nil, 1, 2) --Прилив сил\r\nlocal specWarnOverload\t\t\t\t= mod:NewSpecialWarningDefensive(227257, nil, nil, nil, 3, 6) --Перегрузка\r\n\r\nlocal timerSummonAddCD\t\t\t\t= mod:NewNextTimer(9.5, 227267, nil, nil, nil, 1, nil, DBM_CORE_DAMAGE_ICON) --Призыв нестабильной энергии\r\nlocal timerPowerDischargeCD\t\t\t= mod:NewCDTimer(14, 227279, nil, nil, nil, 3, nil, DBM_CORE_DEADLY_ICON) --Разряд энергии\r\nlocal timerEvoCD\t\t\t\t\t= mod:NewNextTimer(70, 227254, nil, nil, nil, 7) --Прилив сил\r\nlocal timerEvo\t\t\t\t\t\t= mod:NewBuffActiveTimer(20, 227254, nil, nil, nil, 6, nil, DBM_CORE_DEADLY_ICON) --Прилив сил\r\n\r\nlocal countdownEvo\t\t\t\t\t= mod:NewCountdown(70, 227254, nil, nil, 5) --Прилив сил\r\n\r\nlocal countdownPowerDischarge = mod:NewCountdown(13, 227279, true, nil, 3)\r\nmod:AddSetIconOption("SetIconOnUnstableEnergy", 227267, true, true, {8, 7, 6, 5, 4, 3, 2, 1})\r\n\r\nlocal energyIcons = {8, 7, 6, 5, 4, 3, 2, 1}\r\nlocal energyMobs, energyIconOwners = {}, {}\r\nlocal energyUnits = {"target", "mouseover", "boss1", "boss2", "boss3", "boss4", "boss5"}\r\n\r\nlocal function isUnstableEnergy(guid)\r\n\treturn type(guid) == "string" and guid:match("^Creature%-") and mod:GetCIDFromGUID(guid) == 114249\r\nend\r\n\r\nlocal function findEnergyUnit(guid)\r\n\tfor _, unit in ipairs(energyUnits) do\r\n\t\tif UnitGUID(unit) == guid and not UnitIsPlayer(unit) then return unit end\r\n\tend\r\n\tfor member in DBM:GetGroupMembers() do\r\n\t\tlocal unit = member.."target"\r\n\t\tif UnitGUID(unit) == guid and not UnitIsPlayer(unit) then return unit end\r\n\tend\r\nend\r\n\r\nlocal function scanEnergyIcons(self)\r\n\tself:Unschedule(scanEnergyIcons)\r\n\tif not self.inCombat or not self.Options.SetIconOnUnstableEnergy or DBM.Options.DontSetIcons then return end\r\n\tlocal pending = false\r\n\tfor guid, record in pairs(energyMobs) do\r\n\t\tif not record.marked and GetTime() < record.expires then\r\n\t\t\tpending = true\r\n\t\t\tlocal unit = findEnergyUnit(guid)\r\n\t\t\tif unit and not UnitIsDead(unit) and self:CanSetIcon("SetIconOnUnstableEnergy") then\r\n\t\t\t\t-- One synchronous native scan. GUID, not a name/player/target shortcut.\r\n\t\t\t\t-- -1 disables the core\'s optional secondary-CID match; duration 0\r\n\t\t\t\t-- leaves retry ownership here, avoiding shared native scan-state races.\r\n\t\t\t\tself:ScanForMobs(guid, 2, record.icon, 1, 0.2, 0, "SetIconOnUnstableEnergy", false, -1)\r\n\t\t\t\tif UnitGUID(unit) == guid and GetRaidTargetIndex(unit) == record.icon then record.marked = true end\r\n\t\t\tend\r\n\t\tend\r\n\tend\r\n\tif pending then self:Schedule(0.2, scanEnergyIcons, self) end\r\nend\r\n\r\nlocal function resetEnergyIcons(self)\r\n\tself:Unschedule(scanEnergyIcons)\r\n\tfor guid in pairs(energyMobs) do energyMobs[guid] = nil end\r\n\tfor icon in pairs(energyIconOwners) do energyIconOwners[icon] = nil end\r\nend\r\n\r\nmod.vb.powerDischargeCast = 0\r\n\r\nlocal powerDischargesTimers = {14, 14, 14, 45.2, 14, 14, 45.2, 14, 14, 45.2, 14, 14, 45.2, 14, 14, 45.2, 14, 14, 45.2, 14, 14, 45.2}\r\n\r\nlocal function startProshlyapationOfMurchal(self) -- Proshlyapation of Murchal\r\n\tself.vb.powerDischargeCast = self.vb.powerDischargeCast + 1\r\n\tif not UnitIsDeadOrGhost("player") then\r\n\t\tspecWarnPowerDischarge2:Show()\r\n\t\tspecWarnPowerDischarge2:Play("watchstep")\r\n\tend\r\n\tlocal timer = powerDischargesTimers[self.vb.powerDischargeCast+1]\r\n\tif timer then\r\n\t\ttimerPowerDischargeCD:Start(timer, self.vb.powerDischargeCast+1)\r\n\t\tif not UnitIsDeadOrGhost("player") then countdownPowerDischarge:Start(timer) end\r\n\t\tself:Schedule(timer, startProshlyapationOfMurchal, self)\r\n\tend\r\nend\r\n\r\nfunction mod:OnCombatStart(delay)\r\n\tresetEnergyIcons(self)\r\n\tcountdownPowerDischarge:Cancel()\r\n\tself.vb.powerDischargeCast = 0\r\n\tif not self:IsNormal() then\r\n\t\ttimerSummonAddCD:Start(6-delay) --Призыв нестабильной энергии\r\n\t\tspecWarnEvo2:Schedule(48-delay)\r\n\t\tspecWarnEvo2:ScheduleVoice(48-delay, "specialsoon")\r\n\t\ttimerEvoCD:Start(53-delay) --Прилив сил\r\n\t\tcountdownEvo:Start(53) --Прилив сил\r\n\t\ttimerPowerDischargeCD:Start(13-delay) --Разряд энергии\r\n\t\t-- Keep the original warning schedule (including its existing delay behavior).\r\n\t\tif not UnitIsDeadOrGhost("player") then countdownPowerDischarge:Start(13) end\r\n\t\tself:Schedule(13, startProshlyapationOfMurchal, self)\r\n\tend\r\n--\t\ttimerSummonAddCD:Start(6-delay)\r\n--\t\ttimerPowerDischargeCD:Start(13.5)\r\n--\t\ttimerEvoCD:Start(68-delay)\r\n--\t\tcountdownEvo:Start(68)\r\n--\tend\r\nend\r\n\r\nfunction mod:OnCombatEnd()\r\n\tself:Unschedule(startProshlyapationOfMurchal)\r\n\tcountdownPowerDischarge:Cancel()\r\n\tresetEnergyIcons(self)\r\nend\r\n\r\nfunction mod:UNIT_DIED(args)\r\n\tlocal guid = args.destGUID\r\n\tif guid == UnitGUID("player") then countdownPowerDischarge:Cancel() end\r\n\tlocal record = energyMobs[guid]\r\n\tif record then\r\n\t\tenergyIconOwners[record.icon] = nil\r\n\t\tenergyMobs[guid] = nil\r\n\tend\r\nend\r\nmod.UNIT_DESTROYED = mod.UNIT_DIED\r\n\r\nfunction mod:SPELL_SUMMON(args)\r\n\tlocal spellId = args.spellId\r\n\tif spellId == 227267 then --Призыв нестабильной энергии\r\n\t\tlocal guid = args.destGUID\r\n\t\tif self.Options.SetIconOnUnstableEnergy and not DBM.Options.DontSetIcons and isUnstableEnergy(guid) and not energyMobs[guid] then\r\n\t\t\tfor _, icon in ipairs(energyIcons) do\r\n\t\t\t\tif not energyIconOwners[icon] then\r\n\t\t\t\t\tenergyMobs[guid] = {icon = icon, expires = GetTime() + 8, marked = false}\r\n\t\t\t\t\tenergyIconOwners[icon] = guid\r\n\t\t\t\t\tbreak\r\n\t\t\t\tend\r\n\t\t\tend\r\n\t\t\tscanEnergyIcons(self)\r\n\t\tend\r\n\t\twarnAdds:Show()\r\n\t\tif not UnitIsDeadOrGhost("player") then\r\n\t\t\tspecWarnAdds:Show()\r\n\t\t\tspecWarnAdds:Play("switch")\r\n\t\tend\r\n\t\ttimerSummonAddCD:Start()\r\n\tend\r\nend\r\n\r\nfunction mod:SPELL_AURA_APPLIED(args)\r\n\tlocal spellId = args.spellId\r\n\tif spellId == 227254 then --Прилив сил\r\n\t\ttimerSummonAddCD:Stop()\r\n\t--\ttimerPowerDischargeCD:Stop()\r\n\t\twarnEvo:Show()\r\n\t\tif not UnitIsDeadOrGhost("player") then\r\n\t\t\tspecWarnEvo:Show()\r\n\t\t\tspecWarnOverload:Schedule(17)\r\n\t\t\tspecWarnOverload:ScheduleVoice(17, "defensive")\r\n\t\tend\r\n\t\ttimerEvo:Start()\r\n\t\tcountdownEvo:Start(20)\r\n\telseif spellId == 227257 then --Перегрузка\r\n\t\tlocal amount = args.amount or 1\r\n\t\twarnOverload:Show(args.destName, amount)\r\n\tend\r\nend\r\nmod.SPELL_AURA_APPLIED_DOSE = mod.SPELL_AURA_APPLIED\r\n\r\nfunction mod:SPELL_AURA_REMOVED(args)\r\n\tlocal spellId = args.spellId\r\n\tif spellId == 227254 then --Прилив сил\r\n\t\ttimerSummonAddCD:Start(6)\r\n\t--\ttimerPowerDischargeCD:Start(13)\r\n\t\tspecWarnEvo2:Schedule(48.5)\r\n\t\tspecWarnEvo2:ScheduleVoice(48.5, "specialsoon")\r\n\t\ttimerEvoCD:Start(53.5) --для миф0 норм\r\n\t\tcountdownEvo:Start(53.5) --для миф0 норм\r\n\tend\r\nend\r\n\r\nfunction mod:SPELL_PERIODIC_DAMAGE(_, _, _, _, destGUID, _, _, _, spellId)\r\n\tif spellId == 227465 and destGUID == UnitGUID("player") and self:AntiSpam(2, "powerdischarge") then\r\n\t\tif self:IsHard() then\r\n\t\t\tspecWarnPowerDischarge:Show()\r\n\t\t\tspecWarnPowerDischarge:Play("runaway")\r\n\t\tend\r\n\tend\r\nend\r\nmod.SPELL_PERIODIC_MISSED = mod.SPELL_PERIODIC_DAMAGE\r\n\r\n--[[function mod:UNIT_SPELLCAST_SUCCEEDED(uId, _, bfaSpellId, _, legacySpellId)\r\n\tlocal spellId = legacySpellId or bfaSpellId\r\n\tif spellId == 227278 then\r\n\t--\ttimerPowerDischargeCD:Start() --сломано со стороны сервера\r\n\tend\r\nend\r\n\r\n]] -- Close the disabled source handler block.\r\n']]}, {'path': 'DBM-TombofSargeras/DemonicInquisition.lua', 'source': {'path': 'DBM-TombofSargeras/DemonicInquisition.lua', 'mode': 'DONOR', 'donor': 'S01', 'source_path': 'DBM-TombofSargeras/DemonicInquisition.lua', 'sha256': '13bb3d2cc6ea8731a75f603f73abff5b46aca4cdf66e57ee64fc6ec2a3aa23f2'}, 'before_sha256': '13bb3d2cc6ea8731a75f603f73abff5b46aca4cdf66e57ee64fc6ec2a3aa23f2', 'after_sha256': '8b531ac0896bc61952960e08f0a71fe1e93bcc7e7ed167e71cf9230df3b4d40e', 'operations': [[102, 155, 'mod:SetRevision(20261104000001) -- IQ-20261104-01 / private TEST004\r\n'], [12399, 12431, '\telseif spellId == 248713 then\r\n'], [12466, 12510, '\t\tif args:IsPlayer() and amount >= 5 and amount % 5 == 0 then\r\n']]}, {'path': 'DBM-TombofSargeras/Goroth.lua', 'source': {'path': 'DBM-TombofSargeras/Goroth.lua', 'mode': 'DONOR', 'donor': 'S01', 'source_path': 'DBM-TombofSargeras/Goroth.lua', 'sha256': '73dd929efaa4e11ff9b953ce247f837df5586b2bae7381fe49859ec8c26027f6'}, 'before_sha256': '73dd929efaa4e11ff9b953ce247f837df5586b2bae7381fe49859ec8c26027f6', 'after_sha256': 'b57582f701c8038176035a0b7c39b7af9fac6a4c2fc3c3927ae81f9ee3b184dd', 'operations': [[102, 155, 'mod:SetRevision(20261104000002) -- GOROTH-20261104-01 / private TEST005\r\n'], [5718, 5718, '\t\t\tif nextCount == 4 and self:IsHeroic() then timer = 60 end -- Three heroic runs: 60.50-60.55 seconds\r\n'], [8498, 8579, '\t\t\tlocal spellName, _, _, _, _, _, _, _, _, _, spellId = UnitDebuff(uId, i)\r\n']]}, {'path': 'DBM-TombofSargeras/Harjatan.lua', 'source': {'path': 'DBM-TombofSargeras/Harjatan.lua', 'mode': 'DONOR', 'donor': 'S01', 'source_path': 'DBM-TombofSargeras/Harjatan.lua', 'sha256': 'e3eef2cfa24eaeea784821557627b4b8d0f9287b9009cc9d3319b4cacb504257'}, 'before_sha256': 'e3eef2cfa24eaeea784821557627b4b8d0f9287b9009cc9d3319b4cacb504257', 'after_sha256': '413a65d46935e81f89fac12eadadda26f1c13662e93dc293afddeb232478ec36', 'operations': [[102, 155, 'mod:SetRevision(20261103000001) -- RAID-20261103-TEST001 / private TEST002\r\n'], [6018, 6067, '\t\tspecWarnUncheckedRage:ScheduleVoice(17, "gathershare")\r\n']]}]
for row in PATCHES:
 source=row['source'];p=row['path']
 raw=(B/source['folder']/p).read_bytes() if source['mode']=='GENERATED' else S[source['donor']][source['source_path']]
 assert hashlib.sha256(raw).hexdigest()==row['before_sha256'],p
 text=raw.decode('utf8')
 for start,end,replacement in reversed(row['operations']):text=text[:start]+replacement+text[end:]
 raw=text.encode('utf8');assert hashlib.sha256(raw).hexdigest()==row['after_sha256'],p
 dest=B/'common_research_only'/p;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes(raw)
